    # ── backfill: users/roles become organization-scoped ──────────────────
    # Every tenant needs at least one organization before roles/users can be
    # assigned one. The default tenant's system roles were seeded tenant-wide
    # with a NULL organization_id, so backfill before the NOT NULL flips.
    op.execute(sa.text("""
        WITH missing AS (
            SELECT t.id AS tenant_id, gen_random_uuid() AS u
            FROM org_management.tenants t
            WHERE NOT EXISTS (
                SELECT 1 FROM org_management.organizations o
                WHERE o.tenant_id = t.id AND o.deleted_at IS NULL
            )
        )
        INSERT INTO org_management.organizations
            (uuid, tenant_id, parent_id, org_code, legal_name, org_type, hierarchy_path,
             depth, status, is_verified, row_version, app_version, app_metadata, created_at, updated_at)
        SELECT u, tenant_id, NULL, 'DEFAULT-HQ', 'Default HQ', 'solo', '/' || u::text || '/',
               0, 'active', false, 1, '0.1.0', '{}'::jsonb, now(), now()
        FROM missing
    """))
    op.execute(sa.text("""
        UPDATE roles r SET organization_id = (
            SELECT o.id FROM org_management.organizations o
            WHERE o.tenant_id = r.tenant_id AND o.deleted_at IS NULL
            ORDER BY o.depth, o.id LIMIT 1
        ) WHERE r.organization_id IS NULL
    """))
    op.execute(sa.text("""
        UPDATE users u SET organization_id = r.organization_id
        FROM roles r
        WHERE u.role_id = r.id AND r.tenant_id = u.tenant_id
          AND u.organization_id IS DISTINCT FROM r.organization_id
    """))
    op.execute(sa.text("""
        UPDATE users u SET organization_id = (
            SELECT o.id FROM org_management.organizations o
            WHERE o.tenant_id = u.tenant_id AND o.deleted_at IS NULL
            ORDER BY o.depth, o.id LIMIT 1
        ) WHERE u.organization_id IS NULL
    """))
